const iconEmojiRe=/\p{Extended_Pictographic}(?:\uFE0F|\uFE0E)?|[↗↘]/gu;
function replaceEmojiTextNode(node){if(node.parentElement?.closest('.weather-card,.weather-nav-icon'))return;const text=node.nodeValue;if(!text||!iconEmojiRe.test(text)){iconEmojiRe.lastIndex=0;return}iconEmojiRe.lastIndex=0;const frag=document.createDocumentFragment();let last=0;for(const match of text.matchAll(iconEmojiRe)){if(match.index>last)frag.append(document.createTextNode(text.slice(last,match.index)));const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('class','emoji-svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('fill','none');svg.setAttribute('stroke','currentColor');svg.setAttribute('stroke-width','1.7');svg.setAttribute('stroke-linecap','round');svg.setAttribute('stroke-linejoin','round');svg.setAttribute('aria-hidden','true');svg.innerHTML=svgIconShapes[match[0]]||'<path d="m12 3 1.8 6.2L20 12l-6.2 1.8L12 20l-1.8-6.2L4 12l6.2-2.8L12 3Z"/>';frag.append(svg);last=match.index+match[0].length}if(last<text.length)frag.append(document.createTextNode(text.slice(last)));node.replaceWith(frag)}
function replaceEmojis(root){if(!root)return;const nodes=[];if(root.nodeType===Node.TEXT_NODE)nodes.push(root);else{const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode(node){return node.parentElement?.closest('script,style')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT}});while(walker.nextNode())nodes.push(walker.currentNode)}nodes.forEach(replaceEmojiTextNode)}
const emojiObserver=new MutationObserver(records=>{for(const r of records)for(const n of r.addedNodes)replaceEmojis(n)});emojiObserver.observe(document.body,{childList:true,subtree:true});

const STORE='mochi-money-v1';let state={debts:[],transactions:[],currency:'VND',creditorName:'Trần Thị Ngọc Nghi',wheelItems:[]};try{const saved=JSON.parse(localStorage.getItem(STORE)||'null');if(saved)state={...state,...saved}}catch(e){}const demoDebtIds=new Set(['sample-a','sample-b','sample-c','sample-d','sample-e']);state.debts=(Array.isArray(state.debts)?state.debts:[]).filter(d=>!demoDebtIds.has(d.id));state.transactions=(Array.isArray(state.transactions)?state.transactions:[]).filter(t=>!demoDebtIds.has(t.debtId));state.wheelItems=Array.isArray(state.wheelItems)?state.wheelItems:[];state.diceFaces=Array.isArray(state.diceFaces)?state.diceFaces:[];const defaultDiceFaces=["1","2","3","4","5","6"];state.diceFaces=Array.from({length:3},(_,i)=>Array.from({length:6},(_,j)=>String(state.diceFaces[i]?.[j]??defaultDiceFaces[j])));state.diceCount=Math.max(1,Math.min(3,Number(state.diceCount)||1));if(!Array.isArray(state.wheelCategories)){state.wheelCategories=[{id:"default",name:"Mặc định",items:state.wheelItems.slice()}];state.activeWheelCategory="default"}else{state.wheelCategories=state.wheelCategories.filter(c=>c&&typeof c.id==="string"&&typeof c.name==="string"&&Array.isArray(c.items));if(!state.wheelCategories.length)state.wheelCategories=[{id:"default",name:"Mặc định",items:[]}];if(!state.wheelCategories.some(c=>c.id===state.activeWheelCategory))state.activeWheelCategory=state.wheelCategories[0].id}state.activeWheelCategory=state.activeWheelCategory||state.wheelCategories[0].id;state.wheelItems=state.wheelCategories.find(c=>c.id===state.activeWheelCategory)?.items||[];state.calendarEvents=Array.isArray(state.calendarEvents)?state.calendarEvents:[];delete state.diceFaces;delete state.diceCount;try{localStorage.setItem(STORE,JSON.stringify(state))}catch(e){}const icons=['🐻','🐱','🐼','🐰','🐸','🦊','🐹','🐨'];const todayISO=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};function persist(){localStorage.setItem(STORE,JSON.stringify(state));renderAll()}function money(n){return new Intl.NumberFormat('vi-VN',{style:'currency',currency:state.currency,maximumFractionDigits:0}).format(Math.round(Number(n)||0))}function formatAmountInput(v){return String(Math.round(Number(v)||0)).replace(/\B(?=(\d{3})+(?!\d))/g,'.')}function parseMoneyInput(v){return Number(String(v??'').replace(/\D/g,''))||0}function formatMoneyInput(el){const value=el.value,caret=el.selectionStart??value.length,digitsBefore=(value.slice(0,caret).match(/\d/g)||[]).length;const digits=value.replace(/\D/g,'').replace(/^0+(?=\d)/,'');const formatted=digits.replace(/\B(?=(\d{3})+(?!\d))/g,'.');el.value=formatted;let pos=0,count=0;while(pos<formatted.length&&count<digitsBefore){if(/\d/.test(formatted[pos]))count++;pos++}el.setSelectionRange(pos,pos)}function dateObj(s){if(!s)return new Date();const [y,m,d]=s.split('-').map(Number);return new Date(y,m-1,d)}function fmtDate(s,opt={day:'numeric',month:'short',year:'numeric'}){if(!s)return '—';return new Intl.DateTimeFormat('vi-VN',opt).format(dateObj(s))}function daysBetween(a,b){return Math.max(0,Math.floor((dateObj(b)-dateObj(a))/86400000))}function perDayRate(debt){const rate=Number(debt.rate)||0,unit=debt.rateUnit||'month';return unit==='none'?0:unit==='day'?rate/100:unit==='year'?rate/100/365:rate/100/30}function debtStateAt(debt,at=todayISO()){const created=debt.createdAt||debt.startDate;if(created&&at<created)return{principal:0,interest:0,total:0};if(debt.status==='paid'&&!(debt.payments||[]).length)return{principal:0,interest:0,total:0};let principal=Math.max(0,Number(debt.principal)||0),interest=0,cursor=debt.startDate||at;const rate=perDayRate(debt);const payments=(debt.payments||[]).filter(p=>p.date&&p.date<=at).slice().sort((a,b)=>a.date.localeCompare(b.date));for(const p of payments){const payDate=p.date<cursor?cursor:p.date;interest+=principal*rate*daysBetween(cursor,payDate);cursor=payDate;let amount=Math.max(0,Number(p.amount)||0);const toInterest=Math.min(amount,interest);interest-=toInterest;amount-=toInterest;principal=Math.max(0,principal-amount)}interest+=principal*rate*daysBetween(cursor,at);if(principal<0.5)principal=0;if(interest<0.5)interest=0;if(principal+interest<1){principal=0;interest=0}return{principal,interest,total:principal+interest}}function calcInterest(debt,at=todayISO()){return debtStateAt(debt,at).interest}function balance(debt,at=todayISO()){return debtStateAt(debt,at).total}function debtParty(debt){return debt.direction==='payable'?debt.creditor:debt.borrower}function debtRoleInfo(debt){return debt.direction==='payable'?'Người vay: '+debt.borrower:'Chủ nợ: '+debt.creditor}function readEvidenceImage(file){return new Promise((resolve,reject)=>{if(!file){resolve('');return}if(!file.type.startsWith('image/')){reject(new Error('Vui lòng chọn tệp ảnh'));return}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const scale=Math.min(1,1000/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.72))};img.onerror=()=>reject(new Error('Không đọc được ảnh'));img.src=reader.result};reader.onerror=()=>reject(new Error('Không đọc được ảnh'));reader.readAsDataURL(file)})}function previewEvidence(input){const box=input.parentElement.querySelector('.evidence-preview');if(!box)return;const file=input.files?.[0];if(!file){box.innerHTML='';return}if(!file.type.startsWith('image/')){input.value='';toast('Vui lòng chọn tệp ảnh');return}const url=URL.createObjectURL(file);box.innerHTML='<img src="'+url+'" alt="Ảnh giao dịch xem trước">'}
async function saveDebtFromForm(e){e.preventDefault();const f=new FormData(e.target);const id=f.get('id');const old=state.debts.find(d=>d.id===id);let evidence=old?.evidence||'';try{if(f.get('removeEvidence')==='1')evidence='';if(f.get('evidence')?.size)evidence=await readEvidenceImage(f.get('evidence'))}catch(err){toast(err.message);return}const debt={id:id||crypto.randomUUID(),createdAt:old?.createdAt||todayISO(),borrower:f.get('borrower').trim(),creditor:f.get('creditor').trim(),principal:parseMoneyInput(f.get('principal')),rate:f.get('rateUnit')==='none'?0:Number(f.get('rate')||0),rateUnit:f.get('rateUnit'),startDate:f.get('startDate')||todayISO(),dueDate:f.get('dueDate'),note:f.get('note').trim(),evidence,status:old?.status||'active',paidInterest:old?.paidInterest||0,direction:f.get('direction')||'receivable',payments:old?.payments||[],icon:old?.icon||icons[Math.floor(Math.random()*icons.length)]};if(old)state.debts=state.debts.map(d=>d.id===id?debt:d);else state.debts.unshift(debt);closeModal();persist();toast(old?'Đã cập nhật khoản nợ ✨':'Đã thêm khoản nợ mới 🍡')}
function openDebtModal(id){const d=id?state.debts.find(x=>x.id===id):null;document.getElementById('modal').innerHTML=`<div class="modal-head"><h2>${d?'✏️ Sửa khoản nợ':'🍡 Thêm khoản nợ'}</h2><button class="close" onclick="closeModal()">×</button></div><form onsubmit="saveDebtFromForm(event)"><input type="hidden" name="id" value="${d?.id||''}"><div class="form-grid"><div class="field debtor-name-field"><label>Tên con nợ *</label><input name="borrower" required maxlength="70" placeholder="Ví dụ: Nguyễn An" value="${escapeAttr(d?.borrower||'')}"></div><div class="field debtor-evidence-field"><label>Ảnh giao dịch</label><input name="evidence" type="file" accept="image/*" onchange="previewEvidence(this)"><div class="evidence-preview">${d?.evidence?`<img src="${d.evidence}" alt="Ảnh giao dịch"><label class="evidence-remove"><input type="checkbox" name="removeEvidence" value="1"> Xóa ảnh hiện tại</label>`:''}</div></div><input type="hidden" name="creditor" value="${escapeAttr(d?.creditor??state.creditorName??'Mình')}"><input type="hidden" name="direction" value="receivable"><div class="field debt-rate-field"><label>Lãi suất</label><div class="rate-row"><input id="debtRate" name="rate" type="number" min="0" step="0.01" placeholder="0" value="${d?.rate??0}"><select id="debtRateUnit" name="rateUnit"><option value="none" ${(!d||d.rateUnit==='none'||!d.rateUnit)?'selected':''}>Không tính lãi</option><option value="day" ${d?.rateUnit==='day'?'selected':''}>% / ngày</option><option value="month" ${d?.rateUnit==='month'?'selected':''}>% / tháng</option><option value="year" ${d?.rateUnit==='year'?'selected':''}>% / năm</option></select></div></div><div class="field debt-principal-field"><label>Số tiền nợ *</label><input name="principal" type="text" inputmode="numeric" required oninput="formatMoneyInput(this)" placeholder="1.000.000" value="${d?formatAmountInput(d.principal):''}"></div><div class="field debt-start-field"><label>Ngày vay / bắt đầu tính lãi *</label><input name="startDate" type="date" required value="${d?.startDate||d?.createdAt||todayISO()}"></div><div class="field debt-due-field"><label>Hạn trả / ngày nhắc</label><input name="dueDate" type="date" value="${d?.dueDate||''}"></div><div class="field full"><label>Ghi chú (không bắt buộc)</label><textarea name="note" maxlength="250" placeholder="Thêm ghi chú…">${escapeHtml(d?.note||'')}</textarea></div></div><div class="modal-actions"><button type="button" class="soft-btn" onclick="closeModal()">Huỷ</button><button class="primary" type="submit">${d?'Lưu thay đổi':'Lưu khoản nợ'}</button></div></form>`;openModal()}
function toggleDebtDirection(initial=false){const select=document.getElementById('debtDirection'),borrower=document.querySelector('#modal [name=borrower]'),creditor=document.querySelector('#modal [name=creditor]');if(!select||!borrower||!creditor)return;const dir=select.value,prev=select.dataset.lastDirection,owner=state.creditorName||'Trần Thị Ngọc Nghi';if(prev&&prev!==dir){if(dir==='payable'){const other=borrower.value;borrower.value=owner;creditor.value=other===owner?'':other}else{const other=creditor.value;borrower.value=other===owner?'':other;creditor.value=owner}}else if(!prev){if(dir==='payable'&&!borrower.value)borrower.value=owner;if(dir==='receivable'&&!creditor.value)creditor.value=owner}document.getElementById('borrowerLabel').textContent=dir==='payable'?'Tên người vay (bạn) *':'Tên con nợ *';document.getElementById('creditorLabel').textContent=dir==='payable'?'Tên người cho vay *':'Tên chủ nợ *';select.dataset.lastDirection=dir}
function toggleInterestFields(){const none=document.getElementById('debtRateUnit')?.value==='none';const rate=document.getElementById('debtRate'),start=document.getElementById('debtStartDate');if(rate)rate.disabled=none;if(start){start.disabled=none;start.required=!none}const startLabel=document.getElementById('interestStartLabel');if(startLabel)startLabel.textContent=none?'Ngày bắt đầu tính lãi (không áp dụng)':'Ngày bắt đầu tính lãi *';document.getElementById('interestRateField')?.classList.toggle('is-disabled',none);document.getElementById('interestStartField')?.classList.toggle('is-disabled',none);const hint=document.getElementById('interestHint');if(hint)hint.textContent=none?'Khoản nợ không tính lãi; ngày bắt đầu tính lãi đã được khoá.':'Lãi tính theo lãi đơn, tự cập nhật theo ngày kể từ ngày bắt đầu.'}
function saveTxFromForm(e){e.preventDefault();const f=new FormData(e.target),id=f.get('id'),old=state.transactions.find(t=>t.id===id);if(old?.paymentId){toast('Khoản thu/trả nợ cần chỉnh trong lịch sử khoản nợ');return}const tx={...(old||{}),id:id||crypto.randomUUID(),type:f.get('type'),title:f.get('title').trim(),category:f.get('category'),amount:parseMoneyInput(f.get('amount')),date:f.get('date'),note:f.get('note').trim()};if(old)state.transactions=state.transactions.map(t=>t.id===id?tx:t);else state.transactions.unshift(tx);closeModal();persist();toast(old?'Đã cập nhật giao dịch ✨':'Đã lưu giao dịch 🌷')}
function openTxModal(type='expense',id=null){const old=id?state.transactions.find(t=>t.id===id):null;if(old?.paymentId){toast('Khoản thu/trả nợ cần chỉnh trong lịch sử khoản nợ');return}const kind=old?.type||type;document.getElementById('modal').innerHTML=`<div class="modal-head"><h2>${old?'✏️ Sửa giao dịch':'💸 Ghi giao dịch'}</h2><button class="close" onclick="closeModal()">×</button></div><form onsubmit="saveTxFromForm(event)"><input type="hidden" name="id" value="${old?.id||''}"><div class="form-grid"><div class="field"><label>Loại giao dịch *</label><select name="type" id="txType" onchange="updateCategories()"><option value="income" ${kind==='income'?'selected':''}>Thu nhập</option><option value="expense" ${kind==='expense'?'selected':''}>Chi tiêu</option></select></div><div class="field"><label>Số tiền *</label><input name="amount" type="text" inputmode="numeric" required oninput="formatMoneyInput(this)" placeholder="10.000" value="${old?formatAmountInput(old.amount):''}"><span class="field-hint">Ví dụ: 10.000 hoặc 100.000</span></div><div class="field"><label>Nội dung *</label><input name="title" required maxlength="70" placeholder="Ví dụ: Lương tháng 10" value="${escapeAttr(old?.title||'')}"></div><div class="field"><label>Danh mục</label><select name="category" id="txCategory"></select></div><div class="field"><label>Ngày giao dịch *</label><input name="date" type="date" required value="${old?.date||todayISO()}"></div><div class="field full"><label>Ghi chú (không bắt buộc)</label><textarea name="note" maxlength="250" placeholder="Thêm ghi chú…">${escapeHtml(old?.note||'')}</textarea></div></div><div class="modal-actions"><button type="button" class="soft-btn" onclick="closeModal()">Huỷ</button><button class="primary" type="submit">${old?'Lưu thay đổi':'Lưu giao dịch'}</button></div></form>`;openModal();updateCategories(old?.category)}
const categories={income:['Lương','Thưởng','Kinh doanh','Đầu tư','Quà tặng','Thu hồi nợ','Khác'],expense:['Ăn uống','Di chuyển','Nhà cửa','Mua sắm','Hoá đơn','Sức khoẻ','Giải trí','Trả nợ','Khác']};function updateCategories(selected=''){const type=document.getElementById('txType')?.value||'expense';const el=document.getElementById('txCategory');if(el){el.innerHTML=categories[type].map(x=>`<option>${x}</option>`).join('');if(selected&&!categories[type].includes(selected))el.insertAdjacentHTML('beforeend',`<option>${escapeHtml(selected)}</option>`);if(selected)el.value=selected}}

function openEvidence(data){if(!data)return;document.getElementById('modal').innerHTML='<div class="modal-head"><h2>Ảnh giao dịch</h2><button class="close" onclick="closeModal()">×</button></div><img class="evidence-large" src="'+data+'" alt="Ảnh giao dịch">';openModal()}function openModal(){document.getElementById('modalBackdrop').classList.add('open');document.body.style.overflow='hidden'}function closeModal(){document.getElementById('modalBackdrop').classList.remove('open');document.body.style.overflow=''}function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function escapeAttr(s){return escapeHtml(s)}function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2400)}function showPage(page){document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id==='page-'+page));document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.page===page));window.scrollTo({top:0,behavior:'smooth'});if(page==='reminders')renderReminders();if(page==='wheel')renderWheel();if(page==='reports')renderReports();if(page==='market')loadMarketData();if(page==='weather')loadWeather();if(page==='calendar')renderCalendar()}
function closeWelcome(){document.getElementById('welcomePopup').hidden=true}
function addPaymentRecord(d,amount,date,note='',kind='repayment',evidence=''){const paymentId=crypto.randomUUID(),txId=crypto.randomUUID();d.payments=d.payments||[];d.payments.push({id:paymentId,amount,date,note,kind,evidence});const incoming=d.direction!=='payable';state.transactions.unshift({id:txId,type:incoming?'income':'expense',title:(incoming?'Thu nợ · ':'Trả nợ · ')+debtParty(d),category:incoming?'Thu hồi nợ':'Trả nợ',amount,date,note,evidence,debtId:d.id,paymentId});return paymentId}function openRepaymentModal(id,settle=false){const d=state.debts.find(x=>x.id===id);if(!d)return;const total=balance(d);document.getElementById('modal').innerHTML=`<div class="modal-head"><h2>${settle?'✅ Tất toán khoản nợ':'💸 Ghi nhận trả nợ'}</h2><button class="close" onclick="closeModal()">×</button></div><form onsubmit="saveRepayment(event)"><input type="hidden" name="debtId" value="${d.id}"><input type="hidden" name="kind" value="${settle?'settlement':'repayment'}"><div class="form-grid"><div class="field full"><label>${d.direction==='payable'?'Số tiền bạn đã trả':'Số tiền đã nhận'} *</label><input name="amount" type="text" inputmode="numeric" required oninput="formatMoneyInput(this)" placeholder="10.000" value="${settle?formatAmountInput(total):''}"><span class="field-hint">Còn phải ${d.direction==='payable'?'trả':'thu'}: ${money(total)}</span></div><div class="field"><label>Ngày giao dịch *</label><input name="date" type="date" required value="${todayISO()}"></div><div class="field"><label>Ảnh giao dịch (không bắt buộc)</label><input name="evidence" type="file" accept="image/*" onchange="previewEvidence(this)"><div class="evidence-preview"></div></div><div class="field"><label>Ghi chú</label><input name="note" maxlength="120" placeholder="Không bắt buộc"></div></div><div class="modal-actions"><button type="button" class="soft-btn" onclick="closeModal()">Huỷ</button><button class="primary" type="submit">${settle?'Xác nhận tất toán':'Lưu lần trả nợ'}</button></div></form>`;openModal()}async function saveRepayment(e){e.preventDefault();const f=new FormData(e.target),d=state.debts.find(x=>x.id===f.get('debtId'));if(!d)return;let evidence='';try{if(f.get('evidence')?.size)evidence=await readEvidenceImage(f.get('evidence'))}catch(err){toast(err.message);return}const date=f.get('date'),amount=parseMoneyInput(f.get('amount')),available=balance(d,date);if(amount<=0){toast('Nhập số tiền hợp lệ');return}if(amount>available+0.5){alert('Số tiền vượt quá dư nợ tại ngày giao dịch ('+money(available)+').');return}addPaymentRecord(d,Math.min(amount,available),date,String(f.get('note')||'').trim(),f.get('kind'),evidence);if(balance(d)<=0.5){d.status='paid';d.paidDate=date}else d.status='active';closeModal();persist();toast('Đã lưu lần trả nợ và cập nhật Thu & chi ✨')}function deletePayment(debtId,paymentId){if(!confirm('Xoá lần trả nợ này và giao dịch Thu & chi liên quan?'))return;const d=state.debts.find(x=>x.id===debtId);if(!d)return;const wasPaid=d.status==='paid';d.status='active';d.payments=(d.payments||[]).filter(p=>p.id!==paymentId);state.transactions=state.transactions.filter(t=>t.paymentId!==paymentId);if(wasPaid&&balance(d)<=0.5)d.status='paid';persist();toast('Đã xoá lần trả nợ')}function markPaid(id){const d=state.debts.find(x=>x.id===id);if(!d||d.status==='paid')return;const total=balance(d),date=todayISO();if(!confirm('Xác nhận đã '+(d.direction==='payable'?'trả hết':'thu đủ')+' khoản nợ của '+debtParty(d)+'? Dư nợ '+money(total)+' sẽ được tất toán.'))return;if(!confirm('Bạn chắc chắn muốn tất toán khoản nợ này chứ? Sau khi xác nhận, khoản nợ sẽ được đánh dấu đã tất toán.'))return;if(total>0.5)addPaymentRecord(d,total,date,'Tất toán toàn bộ khoản nợ','settlement');d.status='paid';d.paidDate=date;persist();toast('Đã tất toán toàn bộ khoản nợ')}function reopenDebt(id){const d=state.debts.find(x=>x.id===id);if(d&&confirm('Mở lại khoản nợ này?')){const settlement=(d.payments||[]).filter(p=>p.kind==='settlement');d.payments=(d.payments||[]).filter(p=>p.kind!=='settlement');const ids=settlement.map(p=>p.id);state.transactions=state.transactions.filter(t=>!ids.includes(t.paymentId));d.status='active';delete d.paidDate;persist()}}function deleteDebt(id){if(confirm('Xoá khoản nợ này?')){state.debts=state.debts.filter(d=>d.id!==id);state.transactions=state.transactions.filter(t=>t.debtId!==id);persist();toast('Đã xoá khoản nợ')}}function deleteTx(id){const t=state.transactions.find(x=>x.id===id);if(t?.paymentId){const d=state.debts.find(x=>x.id===t.debtId);if(d){deletePayment(d.id,t.paymentId);return}}if(confirm('Xoá giao dịch này?')){state.transactions=state.transactions.filter(x=>x.id!==id);persist();toast('Đã xoá giao dịch')}}
function isOverdue(d){return d.status!=='paid'&&d.dueDate&&d.dueDate<todayISO()}function renderDebts(){const q=(document.getElementById('debtSearch')?.value||'').toLowerCase(),filter=document.getElementById('debtFilter')?.value||'all';const collect=state.debts.filter(d=>d.status!=='paid'&&d.direction!=='payable').reduce((a,d)=>a+balance(d),0),pay=state.debts.filter(d=>d.status!=='paid'&&d.direction==='payable').reduce((a,d)=>a+balance(d),0);if(document.getElementById('totalReceivable'))document.getElementById('totalReceivable').textContent=money(collect);if(document.getElementById('totalPayable'))document.getElementById('totalPayable').textContent=money(pay);let list=state.debts.filter(d=>d.direction!=='payable'&&(d.borrower+' '+d.creditor+' '+(d.note||'')).toLowerCase().includes(q));if(filter==='receivable')list=list.filter(d=>d.direction!=='payable');if(filter==='payable')list=list.filter(d=>d.direction==='payable');if(filter==='active')list=list.filter(d=>d.status!=='paid');if(filter==='overdue')list=list.filter(isOverdue);if(filter==='paid')list=list.filter(d=>d.status==='paid');const root=document.getElementById('debtList');if(!root)return;if(!list.length){root.innerHTML=`<div class="card empty" style="grid-column:1/-1"><span class="empty-emoji">${q||state.debts.length?'🔎':'🍡'}</span>${q||state.debts.length?'Không tìm thấy khoản nợ phù hợp.':'Chưa có khoản nợ nào. Thêm khoản đầu tiên nhé!'}</div>`;return}root.innerHTML=list.map(d=>{const bal=debtStateAt(d),interest=bal.interest,due=isOverdue(d)?'<span class="due-chip" style="background:#ffecec;color:#d35b66">Quá hạn</span>':d.status==='paid'?'<span class="due-chip" style="background:#e6f4eb;color:#3d8f66">Đã tất toán</span>':d.dueDate?'<span class="due-chip">Đến hạn '+fmtDate(d.dueDate,{day:'numeric',month:'short'})+'</span>':'<span class="due-chip" style="background:#f6f1ea;color:#85776b">Đang vay</span>';const payments=(d.payments||[]).slice().sort((a,b)=>b.date.localeCompare(a.date));const party=debtParty(d);return `<article class="debt-card"><div class="debt-card-top"><div class="avatar">${d.icon||'🐻'}</div><div><h3>${escapeHtml(party)} ${d.evidence?`<button type="button" class="evidence-link" onclick="openEvidence('${d.evidence}')" aria-label="Xem ảnh giao dịch khoản nợ">📷</button>`:''}</h3><div class="subline">${escapeHtml(debtRoleInfo(d))}</div></div><div style="margin-left:auto">${due}</div></div><div class="debt-direction-tag">${d.direction==='payable'?'Tôi đi vay':'Tôi cho vay'}</div><div class="debt-main"><div><small>Gốc còn ${d.direction==='payable'?'phải trả':'phải thu'}</small><strong>${money(bal.principal)}</strong></div><div style="text-align:right"><small>Lãi tạm tính</small><strong style="color:#e2546a">${money(interest)}</strong></div></div><div class="debt-breakdown"><span>${d.rateUnit==='none'?'Không tính lãi':'Lãi '+(d.rate||0)+'% / '+(d.rateUnit==='day'?'ngày':d.rateUnit==='year'?'năm':'tháng')}</span><b>${d.rateUnit==='none'?'—':daysBetween(d.startDate,todayISO())+' ngày'}</b></div><div class="debt-breakdown"><span>Tổng tạm tính</span><b>${money(bal.total)}</b></div><div class="debt-card-footer"><span class="due-label">${d.rateUnit==='none'?'Không tính lãi':'Bắt đầu '+fmtDate(d.startDate,{day:'numeric',month:'short',year:'numeric'})}</span><div class="card-actions">${d.status!=='paid'?`<button class="mini-btn" onclick="openRepaymentModal('${d.id}')">${d.direction==='payable'?'Ghi trả':'Ghi thu'}</button>`:''}<button class="mini-btn" onclick="openDebtModal('${d.id}')">Sửa</button>${d.status==='paid'?`<button class="mini-btn" onclick="reopenDebt('${d.id}')">Mở lại</button>`:`<button class="mini-btn" onclick="markPaid('${d.id}')">Tất toán</button>`}<button class="mini-btn" onclick="deleteDebt('${d.id}')">Xoá</button></div></div>${payments.length?`<details class="payment-history"><summary>Lịch sử trả nợ (${payments.length})</summary>${payments.map(p=>`<div class="payment-row"><span>${fmtDate(p.date)}${p.note?` · ${escapeHtml(p.note)}`:''}</span><strong>${money(p.amount)}</strong>${p.evidence?`<button type="button" class="evidence-link" onclick="openEvidence('${p.evidence}')" aria-label="Xem ảnh giao dịch">📷</button>`:''}<button class="mini-btn" onclick="deletePayment('${d.id}','${p.id}')">Xoá</button></div>`).join('')}</details>`:''}${d.note?`<div class="small-muted" style="margin-top:8px">📝 ${escapeHtml(d.note)}</div>`:''}</article>`}).join('')}
function renderTransactions(){const q=(document.getElementById('txSearch')?.value||'').toLowerCase(),filter=document.getElementById('txFilter')?.value||'all',from=document.getElementById('txFrom')?.value||'',to=document.getElementById('txTo')?.value||'';let list=state.transactions.filter(t=>(t.title+' '+t.category+' '+(t.note||'')).toLowerCase().includes(q)&&(filter==='all'||t.type===filter)&&(!from||t.date>=from)&&(!to||t.date<=to)).sort((a,b)=>b.date.localeCompare(a.date));const root=document.getElementById('txTable');if(!list.length){root.innerHTML=`<tr><td colspan="6"><div class="empty"><span class="empty-emoji">🌷</span>Chưa có giao dịch nào.</div></td></tr>`;return}root.innerHTML=list.map(t=>`<tr><td><span class="type-pill ${t.type==='income'?'income-pill':'expense-pill'}">${t.type==='income'?'Thu vào':'Chi ra'}</span></td><td><b>${escapeHtml(t.title)}</b></td><td>${escapeHtml(t.category||'Khác')}</td><td class="date-cell">${fmtDate(t.date)}</td><td class="${t.type==='income'?'positive':'negative'}" style="font-weight:600">${t.type==='income'?'+':'−'} ${money(t.amount)}</td><td><div class="card-actions"><button class="mini-btn" ${t.paymentId?'disabled title="Sửa khoản trả nợ trong lịch sử khoản nợ"':`onclick="openTxModal('${t.type}','${t.id}')"`}>Sửa</button><button class="mini-btn" onclick="deleteTx('${t.id}')">Xoá</button></div></td></tr>`).join('')}
function monthTransactions(date){return state.transactions.filter(t=>{const d=dateObj(t.date),x=dateObj(date);return d.getMonth()===x.getMonth()&&d.getFullYear()===x.getFullYear()})}let chartRange='6';function setChartRange(r){chartRange=r;document.querySelectorAll('.seg-btn').forEach(b=>b.classList.toggle('active',b.dataset.r===r));renderChart()}function moneyShort(n){n=Math.round(Number(n)||0);if(n>=1e9)return (n/1e9).toFixed(n%1e9?1:0).replace('.',',')+' tỷ';if(n>=1e6)return (n/1e6).toFixed(n%1e6?1:0).replace('.',',')+'tr';if(n>=1e3)return Math.round(n/1e3)+'k';return String(n)}function renderChart(){const root=document.getElementById('chart');const now=new Date();let start='';if(chartRange!=='all'){const d=new Date(now.getFullYear(),now.getMonth()-(Number(chartRange)-1),1);start=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`}let list=state.debts.filter(x=>x.direction!=='payable'&&x.status!=='paid'&&(!start||(x.createdAt||x.startDate||'')>=start)).map(x=>({name:debtParty(x),amount:balance(x)})).sort((a,b)=>b.amount-a.amount);if(!list.length){root.innerHTML='<div class="empty" style="padding:20px">Không có con nợ trong khoảng thời gian này</div>';return}const max=Math.max(1,...list.map(m=>m.amount));const w=430,h=150,base=122,top=18,area=w-40,slot=area/list.length,bw=Math.min(38,slot*.5);root.innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Biểu đồ số tiền theo con nợ">${[0,1,2].map(i=>{const y=top+i*(base-top)/2;return `<line x1="16" y1="${y}" x2="${w-10}" y2="${y}" stroke="#f2e6d7" stroke-dasharray="3 5"/>`}).join('')}${list.map((m,i)=>{const x=20+i*slot+(slot-bw)/2,hgt=Math.max(5,m.amount/max*(base-top));const name=m.name.length>6?m.name.slice(0,6)+'…':m.name;return `<rect x="${x}" y="${base-hgt}" width="${bw}" height="${hgt}" rx="9" fill="#f76b9c"><title>${m.name}: ${money(m.amount)}</title></rect><text x="${x+bw/2}" y="${base-hgt-6}" text-anchor="middle" fill="#e14e83" font-size="10" font-weight="600">${moneyShort(m.amount)}</text><text x="${x+bw/2}" y="142" text-anchor="middle" fill="#3b2f28" font-size="11" font-weight="600">${name}</text>`}).join('')}</svg>`}
function dueSorted(){return state.debts.filter(d=>d.status!=='paid'&&d.direction!=='payable'&&d.dueDate).sort((a,b)=>a.dueDate.localeCompare(b.dueDate))}function dayDiffTo(date){return Math.round((dateObj(date)-dateObj(todayISO()))/86400000)}function renderReminders(){const all=dueSorted();const root=document.getElementById('allReminders');if(!root)return;if(!all.length){root.innerHTML='<div class="card empty"><span class="empty-emoji">🌤️</span>Chưa có khoản nào được đặt ngày nhắc. Thêm ngày hẹn trả khi tạo khoản nợ nhé!</div>'}else root.innerHTML=all.map(d=>{const diff=dayDiffTo(d.dueDate),label=diff<0?`Quá hạn ${Math.abs(diff)} ngày`:diff===0?'Đến hạn hôm nay':`Còn ${diff} ngày`;return `<div class="big-reminder"><div class="calendar-tile"><strong>${dateObj(d.dueDate).getDate()}</strong><small>${new Intl.DateTimeFormat('vi-VN',{month:'short'}).format(dateObj(d.dueDate))}</small></div><div class="rem-info"><strong>${d.icon||'🧸'} ${d.direction==='payable'?'Trả cho':'Thu từ'} ${escapeHtml(debtParty(d))} · ${escapeHtml(dueLabel(label))}</strong><p>${escapeHtml(debtRoleInfo(d))} · Tổng tạm tính ${money(balance(d))}</p></div><button class="mini-btn" onclick="copyReminderMessage('${d.id}')">📋 Sao chép tin nhắn</button><button class="mini-btn" onclick="composeReminder('${d.id}')">Soạn tin nhắc</button></div>`}).join('')}
function reminderMessage(d){const due=d.dueDate?` theo hẹn ngày ${fmtDate(d.dueDate)}`:"";return `Chào ${debtParty(d)}, mình xin phép nhắc bạn về khoản tiền ${money(balance(d))}${due}. Khi thuận tiện, bạn sắp xếp thanh toán giúp mình nhé. Cảm ơn bạn nhiều!`}async function copyReminderMessage(id){const d=state.debts.find(x=>x.id===id);if(!d)return;const message=reminderMessage(d);try{await navigator.clipboard.writeText(message);toast("Đã sao chép tin nhắn nhắc nợ")}catch(e){window.prompt("Sao chép tin nhắn nhắc nợ:",message)}}function composeReminder(id){const d=state.debts.find(x=>x.id===id);if(!d)return;const due=d.dueDate?` theo hẹn ngày ${fmtDate(d.dueDate)}`:'';const message=`Chào ${debtParty(d)}, mình nhắn bạn về khoản tiền ${money(balance(d))}${due}. Khi nào thuận tiện, bạn sắp xếp thanh toán giúp mình nhé. Cảm ơn bạn!`;if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(message).then(()=>toast('Đã chép tin nhắn nhắc nợ')).catch(()=>window.prompt('Tin nhắn nhắc nợ (đã soạn sẵn):',message))}else window.prompt('Tin nhắn nhắc nợ (đã soạn sẵn):',message)}function dueLabel(s){return s}function renderDashReminders(){const list=dueSorted().slice(0,3),root=document.getElementById('dashReminders');if(!root)return;root.innerHTML=list.length?list.map(d=>{const diff=dayDiffTo(d.dueDate),date=dateObj(d.dueDate);return `<div class="reminder-item"><div class="reminder-day"><small>${new Intl.DateTimeFormat('vi-VN',{month:'short'}).format(date)}</small>${date.getDate()}</div><p>${escapeHtml(debtParty(d))}<small>${d.direction==='payable'?'Cần trả · ':'Cần thu · '}${diff<0?`Quá hạn ${Math.abs(diff)} ngày`:diff===0?'Đến hạn hôm nay':`Còn ${diff} ngày`} · ${money(balance(d))}</small></p><span>🍡</span></div>`}).join(''):'<div class="empty" style="padding:15px">Chưa có ngày nhắc nào 🌤️</div>'}
function renderDashboard(){const active=state.debts.filter(d=>d.status!=='paid'&&d.direction!=='payable'),principal=active.reduce((a,d)=>a+debtStateAt(d).principal,0),interest=active.reduce((a,d)=>a+debtStateAt(d).interest,0);document.getElementById('totalOwed').textContent=money(principal+interest);document.getElementById('principalTotal').textContent=money(principal);document.getElementById('interestTotal').textContent=money(interest);document.getElementById('debtorCount').textContent=active.length;document.getElementById('overdueCount').textContent=active.filter(isOverdue).length;const recent=state.debts.filter(d=>d.direction!=='payable').slice().sort((a,b)=>(b.startDate||b.createdAt||'').localeCompare(a.startDate||a.createdAt||'')).slice(0,4);document.getElementById('recentDebts').innerHTML=recent.length?recent.map(d=>`<div class="debt-row"><div class="avatar">${d.icon||'🐻'}</div><div class="debt-info"><strong>${escapeHtml(debtParty(d))}</strong><small>${d.status==='paid'?'Đã tất toán':d.rateUnit==='none'?'Không tính lãi':`Lãi ${money(calcInterest(d))}`}</small></div><div class="debt-sum">${money(balance(d))}<small>${d.direction==='payable'?'Cần trả':isOverdue(d)?'Quá hạn':d.dueDate?fmtDate(d.dueDate,{day:'numeric',month:'short'}):'Cần thu'}</small></div></div>`).join(''):'<div class="empty">Chưa có khoản nợ nào</div>';const latest=state.transactions.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4);const recentTx=document.getElementById('recentTx');if(recentTx)recentTx.innerHTML=latest.length?latest.map(t=>`<div class="tx-row"><div class="tx-icon" style="background:${t.type==='income'?'var(--mint2)':'var(--pink2)'}">${t.type==='income'?'💵':'🛍️'}</div><div class="tx-meta"><strong>${escapeHtml(t.title)}</strong><small>${escapeHtml(t.category||'Khác')} · ${fmtDate(t.date)}</small></div><div class="tx-amount ${t.type==='income'?'positive':'negative'}">${t.type==='income'?'+':'−'}${money(t.amount)}</div></div>`).join(''):'<div class="empty"><span class="empty-emoji">🌷</span>Chưa có giao dịch nào</div>';renderChart();renderDashReminders();const overdue=state.debts.filter(d=>d.status!=='paid'&&isOverdue(d)).length;document.getElementById('notifDot').style.display=overdue?'block':'none'}
function setReportPeriod(period){const to=document.getElementById('reportTo'),from=document.getElementById('reportFrom');if(!to||!from)return;const end=new Date(),start=new Date();if(period==='month')start.setDate(1);else start.setDate(start.getDate()-89);to.value=todayISO();from.value=`${start.getFullYear()}-${String(start.getMonth()+1).padStart(2,'0')}-${String(start.getDate()).padStart(2,'0')}`;renderReports()}function renderReports(){const fromEl=document.getElementById('reportFrom'),toEl=document.getElementById('reportTo');if(!fromEl||!toEl)return;if(!fromEl.value||!toEl.value){const x=new Date();fromEl.value=`${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-01`;toEl.value=todayISO()}const from=fromEl.value,to=toEl.value,txs=state.transactions.filter(t=>(!from||t.date>=from)&&(!to||t.date<=to)),income=txs.filter(t=>t.type==='income').reduce((a,t)=>a+t.amount,0),expense=txs.filter(t=>t.type==='expense').reduce((a,t)=>a+t.amount,0);document.getElementById('reportIncome').textContent=money(income);document.getElementById('reportExpense').textContent=money(expense);const net=document.getElementById('reportNet');net.textContent=money(income-expense);net.className=income-expense>=0?'positive':'negative';const groups={};for(const t of txs){const key=(t.type==='income'?'Thu · ':'Chi · ')+(t.category||'Khác');groups[key]=(groups[key]||0)+Number(t.amount||0)}const entries=Object.entries(groups).sort((a,b)=>b[1]-a[1]),max=Math.max(1,...entries.map(x=>x[1]));document.getElementById('categoryReport').innerHTML=entries.length?entries.map(([name,val])=>`<div class="category-line"><div><span>${escapeHtml(name)}</span><b>${money(val)}</b></div><i><u style="width:${Math.max(3,val/max*100)}%;background:${name.startsWith('Thu')?'var(--mint)':'var(--pink)'}"></u></i></div>`).join(''):'<div class="empty">Chưa có giao dịch trong khoảng ngày này.</div>';const points=[];const now=new Date();for(let i=5;i>=0;i--){const first=new Date(now.getFullYear(),now.getMonth()-i,1),last=new Date(first.getFullYear(),first.getMonth()+1,0),date=`${last.getFullYear()}-${String(last.getMonth()+1).padStart(2,'0')}-${String(last.getDate()).padStart(2,'0')}`;const total=state.debts.reduce((a,d)=>a+debtStateAt(d,date).total,0);points.push({label:new Intl.DateTimeFormat('vi-VN',{month:'short'}).format(first),total})}const maxDebt=Math.max(1,...points.map(p=>p.total)),w=390,base=118,top=10,bw=30,gap=28,offset=(w-points.length*(bw+gap)+gap)/2;document.getElementById('debtTrend').innerHTML=`<svg viewBox="0 0 ${w} 150" width="100%" role="img" aria-label="Dư nợ sáu tháng gần nhất">${[0,1,2].map(i=>`<line x1="12" y1="${top+i*(base-top)/2}" x2="${w-12}" y2="${top+i*(base-top)/2}" stroke="#f2e6d7" stroke-dasharray="3 5"/>`).join('')}${points.map((p,i)=>{const h=Math.max(2,p.total/maxDebt*(base-top)),x=offset+i*(bw+gap);return `<rect x="${x}" y="${base-h}" width="${bw}" height="${h}" rx="8" fill="#c98f5f"/><text x="${x+bw/2}" y="138" text-anchor="middle" fill="#b3a496" font-size="10">${p.label}</text><title>${p.label}: ${money(p.total)}</title>`}).join('')}</svg>`}
const wheelColors=['#ff78ad','#8b6cf6','#41c9a5','#ffb84d','#5e9bff','#f47768','#52c5d8','#c17be8'];let wheelRotation=0,wheelBusy=false;
function currentWheelCategory(){return state.wheelCategories.find(c=>c.id===state.activeWheelCategory)||state.wheelCategories[0]}
function syncWheelItems(){const category=currentWheelCategory();state.activeWheelCategory=category.id;state.wheelItems=category.items}
function renderWheel(){const list=document.getElementById('wheelOptions'),canvas=document.getElementById('wheelCanvas');if(!list||!canvas)return;syncWheelItems();const category=currentWheelCategory(),select=document.getElementById('wheelCategorySelect');select.innerHTML=state.wheelCategories.map(c=>`<option value="${escapeAttr(c.id)}">${escapeHtml(c.name)} (${c.items.length})</option>`).join('');select.value=category.id;document.getElementById('wheelOptionCount').textContent=category.items.length;list.innerHTML=category.items.length?category.items.map((item,i)=>`<span class="wheel-chip">${escapeHtml(item)}<button aria-label="Xóa ${escapeAttr(item)}" onclick="removeWheelOption(${i})">×</button></span>`).join(''):'<span class="small-muted">Danh mục này chưa có lựa chọn nào.</span>';const ctx=canvas.getContext('2d'),items=category.items,n=items.length,size=canvas.width,c=size/2,r=c-5;ctx.clearRect(0,0,size,size);if(!n){ctx.beginPath();ctx.arc(c,c,r,0,Math.PI*2);ctx.fillStyle='#ffe4ef';ctx.fill();ctx.fillStyle='#b86b8d';ctx.font='bold 16px "Baloo 2", sans-serif';ctx.textAlign='center';ctx.fillText('Thêm lựa chọn',c,c);document.getElementById('spinButton').disabled=true;return}document.getElementById('spinButton').disabled=n<2||wheelBusy;const slice=Math.PI*2/n;items.forEach((label,i)=>{const start=-Math.PI/2+i*slice,end=start+slice;ctx.beginPath();ctx.moveTo(c,c);ctx.arc(c,c,r,start,end);ctx.closePath();ctx.fillStyle=wheelColors[i%wheelColors.length];ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.stroke();ctx.save();ctx.translate(c,c);ctx.rotate(start+slice/2);ctx.textAlign='right';ctx.textBaseline='middle';ctx.fillStyle='#fff';ctx.font=`700 ${Math.max(10,Math.min(15,180/n))}px "Baloo 2", sans-serif`;const max=Math.max(7,Math.floor(24/n));ctx.fillText(label.length>max?label.slice(0,max-1)+'…':label,r-18,0);ctx.restore()});ctx.beginPath();ctx.arc(c,c,19,0,Math.PI*2);ctx.fillStyle='#df4f8b';ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.stroke()}
function selectWheelCategory(id){state.activeWheelCategory=id;syncWheelItems();persist();renderWheel();document.getElementById('wheelResult').textContent='Đang xem danh mục '+currentWheelCategory().name}
function createWheelCategoryPrompt(){const name=prompt("Nhập tên danh mục mới:");if(name===null)return;const clean=name.trim();if(!clean){toast("Tên danh mục không được để trống");return}if(state.wheelCategories.some(c=>c.name.toLocaleLowerCase()===clean.toLocaleLowerCase())){toast("Danh mục này đã có rồi");return}const category={id:crypto.randomUUID(),name:clean,items:[]};state.wheelCategories.push(category);state.activeWheelCategory=category.id;syncWheelItems();persist();renderWheel();document.getElementById("wheelResult").textContent="Đã tạo danh mục "+clean}function renameWheelCategory(){const category=currentWheelCategory();if(!category)return;const name=prompt('Nhập tên mới cho danh mục:',category.name);if(name===null)return;const clean=name.trim();if(!clean){toast('Tên danh mục không được để trống');return}if(state.wheelCategories.some(c=>c.id!==category.id&&c.name.toLocaleLowerCase()===clean.toLocaleLowerCase())){toast('Tên danh mục này đã có rồi');return}category.name=clean;persist();renderWheel()}
function deleteWheelCategory(){const category=currentWheelCategory();if(!category)return;if(state.wheelCategories.length<2){toast('Cần giữ lại ít nhất một danh mục');return}if(!confirm(`Xóa danh mục "${category.name}" và ${category.items.length} lựa chọn bên trong?`))return;state.wheelCategories=state.wheelCategories.filter(c=>c.id!==category.id);state.activeWheelCategory=state.wheelCategories[0].id;syncWheelItems();persist();renderWheel();document.getElementById('wheelResult').textContent='Đã xóa danh mục'}
function toggleWheelOptions(){const panel=document.getElementById('wheelOptionsPanel'),toggle=document.getElementById('wheelOptionsToggle');panel.hidden=!panel.hidden;toggle.innerHTML=`📋 Danh sách lựa chọn <span id="wheelOptionCount">${currentWheelCategory().items.length}</span>　${panel.hidden?'⌄':'⌃'}`}
function addWheelOption(){const input=document.getElementById('wheelOptionInput'),value=input.value.trim(),category=currentWheelCategory();if(!value){input.focus();return}if(category.items.some(x=>x.toLocaleLowerCase()===value.toLocaleLowerCase())){toast('Lựa chọn này đã có trong danh mục');return}category.items.push(value);syncWheelItems();input.value='';persist();renderWheel();input.focus()}
function removeWheelOption(index){currentWheelCategory().items.splice(index,1);syncWheelItems();persist();renderWheel()}
function clearWheelOptions(){const category=currentWheelCategory();if(!category.items.length)return;if(!confirm(`Xóa tất cả lựa chọn trong danh mục "${category.name}"?`))return;category.items=[];syncWheelItems();wheelBusy=false;const canvas=document.getElementById('wheelCanvas');canvas.ontransitionend=null;canvas.style.transition='none';canvas.style.transform='rotate(0deg)';wheelRotation=0;requestAnimationFrame(()=>canvas.style.transition='');document.getElementById('wheelResult').textContent='Đã xóa tất cả lựa chọn';persist();renderWheel()}
function spinWheel(){const items=currentWheelCategory().items;if(wheelBusy||items.length<2)return;wheelBusy=true;const btn=document.getElementById('spinButton'),canvas=document.getElementById('wheelCanvas'),result=document.getElementById('wheelResult'),n=items.length,index=Math.floor(Math.random()*n),slice=360/n,target=((360-(index*slice+slice/2))%360+360)%360,current=((wheelRotation%360)+360)%360,extra=(target-current+360)%360;wheelRotation+=1800+extra;btn.disabled=true;result.textContent='Đang quay…';canvas.style.transform=`rotate(${wheelRotation}deg)`;canvas.ontransitionend=()=>{canvas.ontransitionend=null;wheelBusy=false;result.innerHTML=`Kết quả: <strong>${escapeHtml(items[index])}</strong>`;renderWheel()}}async function marketFetch(url){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);try{const response=await fetch(url,{cache:"no-store",signal:controller.signal});if(!response.ok)throw new Error("HTTP "+response.status);return await response.json()}finally{clearTimeout(timer)}}
function marketTime(value){if(!value)return "";const date=typeof value==="number"?new Date(value*1000):new Date(value);return Number.isNaN(date.getTime())?"":new Intl.DateTimeFormat("vi-VN",{dateStyle:"short",timeStyle:"short",timeZone:"Asia/Ho_Chi_Minh"}).format(date)}
async function loadMarketData(){const updated=document.getElementById("marketUpdated");if(updated)updated.textContent="Đang lấy dữ liệu mới…";const goldTask=marketFetch("https://giavang.now/api/prices?type=SJL1L10").then(json=>{const rows=Array.isArray(json.data)?json.data:json.data?[json.data]:[json],gold=rows.find(x=>x&&(x.type_code==="SJL1L10"||x.code==="SJL1L10"))||rows[0];if(json.success===false||!gold||!Number(gold.buy)||!Number(gold.sell))throw new Error("Không có giá vàng");const goldFormat=value=>new Intl.NumberFormat("vi-VN").format(Math.round(value))+" ₫";document.getElementById("goldBuy").textContent=goldFormat(gold.buy);document.getElementById("goldSell").textContent=goldFormat(gold.sell);[["goldBuyChi",gold.buy/10],["goldSellChi",gold.sell/10],["goldBuyPhan",gold.buy/100],["goldSellPhan",gold.sell/100]].forEach(([id,value])=>document.getElementById(id).textContent=goldFormat(value));const t=marketTime(gold.update_time||json.current_time||gold.updatedAt);return t}).catch(()=>{document.getElementById("goldBuy").textContent="Chưa lấy được giá";document.getElementById("goldSell").textContent="Chưa lấy được giá";return ""});const fxTask=marketFetch("https://api.frankfurter.dev/v2/rate/usd/vnd").then(rate=>{if(!Number(rate.rate))throw new Error("Không có tỷ giá");document.getElementById("usdVnd").textContent=new Intl.NumberFormat("vi-VN",{maximumFractionDigits:0}).format(rate.rate)+" ₫";const t=rate.date||"";return t}).catch(()=>{document.getElementById("usdVnd").textContent="Chưa lấy được tỷ giá";return ""});const times=await Promise.all([goldTask,fxTask]);if(updated)updated.textContent="Dữ liệu trực tiếp · vàng cập nhật theo nguồn, tỷ giá USD/VND cập nhật theo ngày"}let weatherPlace=null;try{weatherPlace=JSON.parse(localStorage.getItem('mochi-weather-place')||'null')}catch(e){}
function weatherDescription(code){return ({0:['Nắng','☀️'],1:['Trời quang','🌤️'],2:['Ít mây','⛅'],3:['Nhiều mây','☁️'],45:['Sương mù','🌫️'],48:['Sương muối','🌫️'],51:['Mưa phùn nhẹ','🌦️'],53:['Mưa phùn','🌦️'],55:['Mưa phùn dày','🌧️'],56:['Mưa phùn băng nhẹ','🌧️'],57:['Mưa phùn băng','🌧️'],61:['Mưa nhẹ','🌦️'],63:['Mưa vừa','🌧️'],65:['Mưa to','🌧️'],66:['Mưa băng nhẹ','🌧️'],67:['Mưa băng','🌧️'],71:['Tuyết nhẹ','🌨️'],73:['Tuyết vừa','🌨️'],75:['Tuyết dày','❄️'],77:['Hạt tuyết','🌨️'],80:['Mưa rào nhẹ','🌦️'],81:['Mưa rào','🌧️'],82:['Mưa rào lớn','⛈️'],85:['Mưa tuyết nhẹ','🌨️'],86:['Mưa tuyết lớn','🌨️'],95:['Dông','⛈️'],96:['Dông mưa đá nhẹ','⛈️'],99:['Dông mưa đá','⛈️']})[Number(code)]||['Thời tiết chưa rõ','🌤️']}
function saveWeatherPlace(place){weatherPlace=place;try{localStorage.setItem('mochi-weather-place',JSON.stringify(place))}catch(e){}}
async function fetchWeatherFor(place){const status=document.getElementById('weatherStatus');status.textContent='Đang tải thời tiết…';const query=new URLSearchParams({latitude:place.latitude,longitude:place.longitude,current:'temperature_2m,relative_humidity_2m,apparent_temperature,is_day,precipitation,weather_code,wind_speed_10m',daily:'weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max',timezone:'auto',forecast_days:'4'});const data=await marketFetch('https://api.open-meteo.com/v1/forecast?'+query.toString());if(!data.current||!data.daily)throw new Error('Dữ liệu thời tiết không đầy đủ');const current=data.current,[description,icon]=weatherDescription(current.weather_code),time=current.time?new Date(current.time):new Date();status.textContent=place.name+' · cập nhật '+new Intl.DateTimeFormat('vi-VN',{hour:'2-digit',minute:'2-digit',day:'numeric',month:'short',timeZone:place.timezone||'Asia/Ho_Chi_Minh'}).format(time);document.getElementById('weatherCurrent').innerHTML=`<span class="weather-current-icon">${icon}</span><div class="weather-current-main"><strong>${Math.round(current.temperature_2m)}°C</strong><span>${description} · cảm giác ${Math.round(current.apparent_temperature)}°C</span><div class="weather-current-details"><span>💧 Độ ẩm ${Math.round(current.relative_humidity_2m)}%</span><span>🌬️ Gió ${Math.round(current.wind_speed_10m)} km/h</span><span>🌧️ Mưa ${Number(current.precipitation||0).toLocaleString('vi-VN')} mm</span></div></div>`;const daily=data.daily,days=daily.time.slice(1,4);document.getElementById('weatherForecast').innerHTML=days.map((day,index)=>{const i=index+1,[desc,emoji]=weatherDescription(daily.weather_code[i]),date=new Date(day+'T12:00:00'),label=new Intl.DateTimeFormat('vi-VN',{weekday:'short',day:'numeric',month:'numeric'}).format(date);return `<div class="weather-day"><strong>${label}</strong><span class="weather-icon">${emoji}</span><small>${desc}</small><span>${Math.round(daily.temperature_2m_max[i])}° / ${Math.round(daily.temperature_2m_min[i])}°</span><small>☔ ${daily.precipitation_probability_max?.[i]??0}%</small></div>`}).join('')}
async function loadWeatherByCity(city){const name=String(city||document.getElementById('weatherCitySelect').value).trim();if(!name)return;document.getElementById('weatherCitySelect').value=name;document.getElementById('weatherStatus').textContent='Đang tìm thành phố…';try{const params=new URLSearchParams({name,count:'8',language:'vi',format:'json'}),geo=await marketFetch('https://geocoding-api.open-meteo.com/v1/search?'+params.toString()),results=geo.results||[];if(!results.length)throw new Error('Không tìm thấy thành phố');const place=results.find(x=>x.country_code==='VN')||results[0],saved={name:[place.name,place.admin1,place.country].filter(Boolean).join(', '),latitude:place.latitude,longitude:place.longitude,timezone:place.timezone||'Asia/Ho_Chi_Minh',cityKey:name};saveWeatherPlace(saved);await fetchWeatherFor(saved)}catch(e){document.getElementById('weatherStatus').textContent='Không tìm được thời tiết. Hãy kiểm tra tên thành phố hoặc kết nối mạng.'}}
async function loadWeatherByLocation(){if(!navigator.geolocation){document.getElementById('weatherStatus').textContent='Trình duyệt không hỗ trợ định vị. Hãy nhập tên thành phố.';return}document.getElementById('weatherStatus').textContent='Đang xin vị trí…';navigator.geolocation.getCurrentPosition(async position=>{const coords=position.coords,place={name:'Vị trí của tôi',latitude:coords.latitude,longitude:coords.longitude,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||'Asia/Ho_Chi_Minh'};document.getElementById('weatherCitySelect').value='';saveWeatherPlace(place);try{await fetchWeatherFor(place)}catch(e){document.getElementById('weatherStatus').textContent='Không tải được thời tiết tại vị trí này.'}},error=>{document.getElementById('weatherStatus').textContent=error.code===1?'Bạn chưa cho phép vị trí. Hãy nhập tên thành phố để xem thời tiết.':'Không lấy được vị trí. Hãy nhập tên thành phố.'},{enableHighAccuracy:false,timeout:10000,maximumAge:600000})}
function loadWeather(){const select=document.getElementById('weatherCitySelect');if(weatherPlace&&Number.isFinite(Number(weatherPlace.latitude))&&Number.isFinite(Number(weatherPlace.longitude))&&(weatherPlace.cityKey||weatherPlace.name==='Vị trí của tôi')){select.value=weatherPlace.cityKey||'';fetchWeatherFor(weatherPlace).catch(()=>document.getElementById('weatherStatus').textContent='Không tải được dữ liệu thời tiết. Hãy thử lại sau.')}else loadWeatherByCity('Cần Thơ')}const CAL_TZ=7;let calendarViewDate=new Date(),selectedCalendarDate=todayISO();
function lunarJd(d,m,y){const a=Math.floor((14-m)/12),yy=y+4800-a,mm=m+12*a-3;let jd=d+Math.floor((153*mm+2)/5)+365*yy+Math.floor(yy/4)-Math.floor(yy/100)+Math.floor(yy/400)-32045;if(jd<2299161)jd=d+Math.floor((153*mm+2)/5)+365*yy+Math.floor(yy/4)-32083;return jd}
