function lunarSunLongitude(jdn){const T=(jdn-2451545)/36525,T2=T*T,dr=Math.PI/180,M=357.5291+35999.0503*T-0.0001559*T2-0.00000048*T*T2,L0=280.46645+36000.76983*T+0.0003032*T2,DL=(1.9146-0.004817*T-0.000014*T2)*Math.sin(M*dr)+(0.019993-0.000101*T)*Math.sin(2*M*dr)+0.00029*Math.sin(3*M*dr),omega=125.04-1934.136*T;let L=(L0+DL-0.00569-0.00478*Math.sin(omega*dr))*dr;return (L%(2*Math.PI)+2*Math.PI)%(2*Math.PI)}
