function calendarDateKey(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function holidaysForDate(iso,lunar=solarToVietnameseLunar(iso)){const [year,month,day]=iso.split('-').map(Number),out=[];const solar={ '1-1':'Tết Dương lịch','3-8':'Ngày Quốc tế Phụ nữ','30-4':'Ngày Giải phóng miền Nam','1-5':'Quốc tế Lao động','1-6':'Quốc tế Thiếu nhi','27-7':'Ngày Thương binh - Liệt sĩ','2-9':'Quốc khánh','20-10':'Ngày Phụ nữ Việt Nam','20-11':'Ngày Nhà giáo Việt Nam'};const sk=`${day}-${month}`;if(solar[sk])out.push(solar[sk]);if(lunar.month===1&&lunar.day<=3)out.push(lunar.day===1?'Tết Nguyên Đán':'Tết Nguyên Đán');const lunarMap={'15-1':'Rằm tháng Giêng','10-3':'Giỗ Tổ Hùng Vương','15-4':'Lễ Phật Đản','5-5':'Tết Đoan Ngọ','15-7':'Vu Lan - Rằm tháng Bảy','15-8':'Tết Trung Thu','23-12':'Ông Công, Ông Táo'};const lk=`${lunar.day}-${lunar.month}`;if(lunarMap[lk])out.push(lunarMap[lk]);return out}
function eventMatchesCalendarDate(event,iso,lunar=solarToVietnameseLunar(iso)){if(event.repeat==='lunar')return event.lunarDay===lunar.day&&event.lunarMonth===lunar.month;if(event.repeat==='solar')return event.date.slice(5)===iso.slice(5);return event.date===iso}
function personalEventsForDate(iso,lunar){return state.calendarEvents.filter(event=>eventMatchesCalendarDate(event,iso,lunar))}
function changeCalendarMonth(delta){calendarViewDate=new Date(calendarViewDate.getFullYear(),calendarViewDate.getMonth()+delta,1);renderCalendar()}
function selectCalendarDate(iso){selectedCalendarDate=iso;renderCalendar()}
function renderCalendar(){const grid=document.getElementById('calendarGrid');if(!grid)return;const year=calendarViewDate.getFullYear(),month=calendarViewDate.getMonth(),first=new Date(year,month,1),offset=(first.getDay()+6)%7,total=Math.ceil((offset+new Date(year,month+1,0).getDate())/7)*7;document.getElementById('calendarMonthTitle').textContent=new Intl.DateTimeFormat('vi-VN',{month:'long',year:'numeric'}).format(first);const today=todayISO();grid.innerHTML=Array.from({length:total},(_,i)=>{const date=new Date(year,month,1-offset+i),iso=calendarDateKey(date),lunar=solarToVietnameseLunar(iso),holidays=holidaysForDate(iso,lunar),events=personalEventsForDate(iso,lunar),classes=['calendar-day',date.getMonth()!==month?'outside':'',iso===today?'today':'',iso===selectedCalendarDate?'selected':''].filter(Boolean).join(' '),label=`${date.getDate()} dương lịch, ngày ${lunar.day} tháng ${lunar.month} âm lịch`;return `<button class="${classes}" type="button" aria-label="${label}" title="${[...holidays,...events.map(e=>e.title)].join(' · ')}" onclick="selectCalendarDate('${iso}')"><span class="solar-day">${date.getDate()}</span><span class="lunar-day">${lunar.day}${lunar.day===1?'/'+lunar.month:''}</span><span class="calendar-markers">${holidays.length?'<i class="holiday-dot"></i>':''}${events.length?'<i class="personal-dot"></i>':''}</span></button>`}).join('');const selectedLunar=solarToVietnameseLunar(selectedCalendarDate),selected=new Date(selectedCalendarDate+'T12:00:00');document.getElementById('calendarSelectedTitle').textContent=new Intl.DateTimeFormat('vi-VN',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(selected)+` · ${selectedLunar.day}/${selectedLunar.month} âm lịch`;const holidays=holidaysForDate(selectedCalendarDate,selectedLunar),events=personalEventsForDate(selectedCalendarDate,selectedLunar),items=[...holidays.map(name=>`<div class="calendar-event-item holiday"><span>🎉</span><span class="event-title">${escapeHtml(name)}</span></div>`),...events.map(event=>`<div class="calendar-event-item"><span>💗</span><span class="event-title">${escapeHtml(event.title)}${event.remind?' · có nhắc':''}</span><button type="button" aria-label="Xóa ${escapeAttr(event.title)}" onclick="deleteCalendarEvent('${event.id}')">×</button></div>`)].join('');document.getElementById('calendarSelectedItems').innerHTML=items||'<div class="calendar-event-empty">Chưa có ngày lễ hay lịch riêng.</div>';document.getElementById('calendarEventTitle').value='';renderCalendarUpcoming()}
function saveCalendarEvent(event){event.preventDefault();const form=event.currentTarget,title=String(new FormData(form).get('title')||'').trim();if(!title)return;const date=selectedCalendarDate,lunar=solarToVietnameseLunar(date),repeat=new FormData(form).get('repeat'),remind=form.elements.remind.checked;state.calendarEvents.push({id:crypto.randomUUID(),title,date,repeat,lunarDay:lunar.day,lunarMonth:lunar.month,remind});persist();selectedCalendarDate=date;renderCalendar();toast('Đã lưu ngày cá nhân');if(remind&&'Notification'in window&&Notification.permission==='default')Notification.requestPermission().then(permission=>{if(permission!=='granted')toast('Đã lưu lịch; bật thông báo trình duyệt để nhận nhắc')});checkCalendarReminders()}
function deleteCalendarEvent(id){if(!confirm('Xóa ngày cá nhân này khỏi lịch?'))return;state.calendarEvents=state.calendarEvents.filter(event=>event.id!==id);persist();renderCalendar();toast('Đã xóa ngày cá nhân')}
function renderCalendarUpcoming(){const root=document.getElementById('calendarUpcoming');if(!root)return;const entries=[],start=new Date();start.setHours(12,0,0,0);for(let offset=0;offset<30;offset++){const date=new Date(start);date.setDate(start.getDate()+offset);const iso=calendarDateKey(date),lunar=solarToVietnameseLunar(iso);for(const name of holidaysForDate(iso,lunar))entries.push({iso,title:name,holiday:true});for(const event of personalEventsForDate(iso,lunar))entries.push({iso,title:event.title,eventId:event.id,remind:event.remind})}entries.sort((a,b)=>a.iso.localeCompare(b.iso));root.innerHTML=entries.length?`<div class="calendar-upcoming-list">${entries.slice(0,10).map(item=>`<div class="calendar-upcoming-item"><div class="calendar-upcoming-date">${new Intl.DateTimeFormat('vi-VN',{day:'numeric',month:'short'}).format(new Date(item.iso+'T12:00:00'))}</div><div class="calendar-upcoming-info"><strong>${item.holiday?'🎉 ':'💗 '}${escapeHtml(item.title)}</strong><small>${item.holiday?'Ngày lễ/Tết':item.remind?'Ngày cá nhân · có nhắc':'Ngày cá nhân'}</small></div>${item.eventId?`<button type="button" onclick="deleteCalendarEvent('${item.eventId}')" aria-label="Xóa ${escapeAttr(item.title)}">×</button>`:''}</div>`).join('')}</div>`:'<div class="calendar-upcoming-empty">30 ngày tới chưa có lịch riêng hay ngày lễ.</div>'}
function checkCalendarReminders(){if(!Array.isArray(state.calendarEvents))return;const today=todayISO(),lunar=solarToVietnameseLunar(today);state.calendarEvents.filter(event=>event.remind&&eventMatchesCalendarDate(event,today,lunar)).forEach(event=>{const key=`mochi-calendar-notified-${today}-${event.id}`;if(localStorage.getItem(key))return;localStorage.setItem(key,'1');if('Notification'in window&&Notification.permission==='granted'&&document.hidden)new Notification('Mochi Money · Nhắc lịch',{body:event.title});else toast('📅 Hôm nay: '+event.title)})}function renderAll(){renderDashboard();renderCalendar();renderDebts();renderTransactions();renderReminders();renderReports();if(document.getElementById('currencySelect'))document.getElementById('currencySelect').value=state.currency||'VND';if(document.getElementById('creditorNameSetting'))document.getElementById('creditorNameSetting').value=state.creditorName||'Trần Thị Ngọc Nghi';if(document.getElementById('brandCreditorName'))document.getElementById('brandCreditorName').textContent=state.creditorName||'Trần Thị Ngọc Nghi'}function requestNotifications(){if(!('Notification'in window)){toast('Trình duyệt chưa hỗ trợ thông báo');return}Notification.requestPermission().then(p=>{renderReminders();if(p==='granted'){notifyDue();toast('Đã bật thông báo 🔔')}else toast('Chưa cấp quyền thông báo')})}function notifyDue(){if(!('Notification'in window)||Notification.permission!=='granted')return;const due=dueSorted().filter(d=>dayDiffTo(d.dueDate)<=0);if(!due.length)return;const stamp=todayISO(),key='mochi-notified-'+stamp;if(localStorage.getItem(key))return;new Notification('Mochi Money · Nhắc nợ',{body:`Bạn có ${due.length} khoản cần nhắc hôm nay hoặc đã quá hạn.`});localStorage.setItem(key,'1')}
function exportData(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`mochi-money-backup-${todayISO()}.json`;a.click();URL.revokeObjectURL(a.href)}function importData(event){const file=event.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const x=JSON.parse(reader.result);if(!Array.isArray(x.debts)||!Array.isArray(x.transactions))throw new Error();if(confirm('Nhập bản sao lưu và thay thế dữ liệu hiện tại?')){state={debts:x.debts,transactions:x.transactions,currency:x.currency||'VND',creditorName:x.creditorName||'Trần Thị Ngọc Nghi',wheelItems:Array.isArray(x.wheelItems)?x.wheelItems:[],wheelCategories:Array.isArray(x.wheelCategories)?x.wheelCategories:[{id:'default',name:'Mặc định',items:Array.isArray(x.wheelItems)?x.wheelItems:[]}],activeWheelCategory:x.activeWheelCategory||'default',calendarEvents:Array.isArray(x.calendarEvents)?x.calendarEvents:[]};persist();toast('Đã nhập dữ liệu thành công ✨')}}catch(e){alert('Tệp sao lưu không hợp lệ.')}event.target.value=''};reader.readAsText(file)}function setCreditorName(v){const name=String(v||'').trim();if(!name){toast('Vui lòng nhập tên tài khoản');return}state.creditorName=name;persist();toast('Đã lưu tên chủ nợ mặc định ✨')}function setCurrency(v){state.currency=v;persist();toast('Đã cập nhật tiền tệ')}function clearAll(){if(confirm('Bạn chắc chắn muốn xoá toàn bộ khoản nợ và giao dịch? Không thể hoàn tác.')){state={debts:[],transactions:[],currency:state.currency||'VND',creditorName:state.creditorName||'Trần Thị Ngọc Nghi',wheelItems:state.wheelItems||[],wheelCategories:state.wheelCategories||[{id:'default',name:'Mặc định',items:[]}],activeWheelCategory:state.activeWheelCategory||'default',calendarEvents:state.calendarEvents||[]};persist();toast('Đã xoá toàn bộ dữ liệu')}}
const today=new Date();document.getElementById('todayText').textContent=new Intl.DateTimeFormat('vi-VN',{weekday:'short',day:'numeric',month:'short',year:'numeric'}).format(today);document.getElementById('dateSubtitle').textContent=new Intl.DateTimeFormat('vi-VN',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(today);renderAll();replaceEmojis(document.body);loadMarketData();setInterval(loadMarketData,5*60*1000);setInterval(checkCalendarReminders,60*1000);checkCalendarReminders();setInterval(()=>{if(!document.hidden&&document.getElementById("page-weather").classList.contains("active"))loadWeather()},15*60*1000);notifyDue();window.addEventListener('storage',e=>{if(e.key===STORE&&e.newValue){try{state={...state,...JSON.parse(e.newValue)};renderAll();toast('Dữ liệu đã đồng bộ giữa các tab ✨')}catch(err){}}});window.addEventListener('focus',notifyDue);document.addEventListener('visibilitychange',()=>{if(!document.hidden)notifyDue()});setInterval(()=>{if(!document.hidden)notifyDue()},5*60*1000);window.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});